package com.riwaaz.backend;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/auth")@CrossOrigin("http://localhost:5173")public class AuthController{@PostMapping("/register")public Map<String,Object> r(@RequestBody Map<String,String>b){return Map.of("message","Registration successful","user",b);}@PostMapping("/login")public Map<String,Object> l(@RequestBody Map<String,String>b){return Map.of("token","demo-jwt-token","user",Map.of("email",b.get("email"),"role","USER"));}@GetMapping("/profile")public Map<String,Object> p(){return Map.of("name","Demo User","role","USER");}}